B.bxK=new A.ec("This PDF is a scan with no text in it. Take a screenshot of it and check that.","\u092f\u0947 PDF \u0938\u094d\u0915\u0948\u0928 \u0939\u0948, \u0907\u0938\u092e\u0947\u0902 \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0907\u0938\u0915\u093e \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u0932\u0947\u0915\u0930 \u091c\u093e\u0902\u091a\u0947\u0902\u0964","\u0939\u0940 PDF \u0938\u094d\u0915\u0945\u0928 \u0906\u0939\u0947, \u0924\u093f\u091a\u094d\u092f\u093e\u0924 \u092e\u091c\u0915\u0942\u0930 \u0928\u093e\u0939\u0940. \u0924\u093f\u091a\u093e \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u0918\u0947\u090a\u0928 \u0924\u092a\u093e\u0938\u093e.")
B.bxL=new A.ec("Call 1930, the cyber fraud helpline","1930 \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902, \u0938\u093e\u0907\u092c\u0930 \u092b\u094d\u0930\u0949\u0921 \u0939\u0947\u0932\u094d\u092a\u0932\u093e\u0907\u0928","1930 \u0935\u0930 \u0915\u0949\u0932 \u0915\u0930\u093e, \u0938\u093e\u092f\u092c\u0930 \u092b\u0938\u0935\u0923\u0942\u0915 \u0939\u0947\u0932\u094d\u092a\u0932\u093e\u0907\u0928")
B.bxM=new A.ec("No known red flags, still verify","\u0915\u094b\u0908 \u091c\u093e\u0928\u093e-\u092a\u0939\u091a\u093e\u0928\u093e \u0916\u0924\u0930\u093e \u0928\u0939\u0940\u0902 \u0926\u093f\u0916\u093e, \u092b\u093f\u0930 \u092d\u0940 \u091c\u093e\u0902\u091a \u0932\u0947\u0902","\u0913\u0933\u0916\u0940\u091a\u093e \u0927\u094b\u0915\u093e \u0926\u093f\u0938\u0932\u093e \u0928\u093e\u0939\u0940, \u0924\u0930\u0940\u0939\u0940 \u0916\u093e\u0924\u094d\u0930\u0940 \u0915\u0930\u093e")
B.bxN=new A.ec("Phone numbers, UPI IDs and names from the message are hidden on the card.","\u092e\u0948\u0938\u0947\u091c \u0915\u0947 \u092b\u093c\u094b\u0928 \u0928\u0902\u092c\u0930, UPI ID \u0914\u0930 \u0928\u093e\u092e \u0915\u093e\u0930\u094d\u0921 \u092a\u0930 \u091b\u0941\u092a\u093e \u0926\u093f\u090f \u0917\u090f \u0939\u0948\u0902\u0964","\u092e\u0947\u0938\u0947\u091c\u092e\u0927\u0932\u0947 \u092b\u094b\u0928 \u0928\u0902\u092c\u0930, UPI ID \u0906\u0923\u093f \u0928\u093e\u0935\u0902 \u0915\u093e\u0930\u094d\u0921\u0935\u0930 \u0932\u092a\u0935\u0932\u0940 \u0906\u0939\u0947\u0924.")
B.bxO=new A.ec("Lost money? Call 1930 or report on cybercrime.gov.in","\u092a\u0948\u0938\u0947 \u0917\u090f? 1930 \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902 \u092f\u093e cybercrime.gov.in \u092a\u0930 \u0936\u093f\u0915\u093e\u092f\u0924 \u0915\u0930\u0947\u0902","\u092a\u0948\u0938\u0947 \u0917\u0947\u0932\u0947? 1930 \u0935\u0930 \u0915\u0949\u0932 \u0915\u0930\u093e \u0915\u093f\u0902\u0935\u093e cybercrime.gov.in \u0935\u0930 \u0924\u0915\u094d\u0930\u093e\u0930 \u0915\u0930\u093e")
B.bxP=new A.ec("Report it","\u0936\u093f\u0915\u093e\u092f\u0924 \u0915\u0930\u0947\u0902","\u0924\u0915\u094d\u0930\u093e\u0930 \u0915\u0930\u093e")
B.bxQ=new A.ec("From the message, with numbers and names hidden","\u092e\u0948\u0938\u0947\u091c \u0938\u0947, \u0928\u0902\u092c\u0930 \u0914\u0930 \u0928\u093e\u092e \u091b\u0941\u092a\u093e\u0915\u0930","\u092e\u0947\u0938\u0947\u091c\u092e\u0927\u0942\u0928, \u0928\u0902\u092c\u0930 \u0906\u0923\u093f \u0928\u093e\u0935\u0902 \u0932\u092a\u0935\u0942\u0928")
B.bxR=new A.ec("Check it","\u091c\u093e\u0902\u091a\u0947\u0902","\u0924\u092a\u093e\u0938\u093e")
B.bxS=new A.ec("Choose a PDF","PDF \u091a\u0941\u0928\u0947\u0902","PDF \u0928\u093f\u0935\u0921\u093e")
B.bxT=new A.ec("Nox reads it in this browser. Nothing is uploaded.","Nox \u0907\u0938\u0947 \u0907\u0938\u0940 \u092c\u094d\u0930\u093e\u0909\u091c\u093c\u0930 \u092e\u0947\u0902 \u092a\u0922\u093c\u0924\u093e \u0939\u0948\u0964 \u0915\u0941\u091b \u092d\u0940 \u0905\u092a\u0932\u094b\u0921 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964","Nox \u0939\u0947 \u092f\u093e\u091a \u092c\u094d\u0930\u093e\u0909\u091d\u0930\u092e\u0927\u094d\u092f\u0947 \u0935\u093e\u091a\u0924\u094b. \u0915\u093e\u0939\u0940\u0939\u0940 \u0905\u092a\u0932\u094b\u0921 \u0939\u094b\u0924 \u0928\u093e\u0939\u0940.")
B.bxU=new A.ec("Checked on my phone with NO SUS \xb7 nosus.foo","\u092e\u0947\u0930\u0947 \u092b\u093c\u094b\u0928 \u092a\u0930 NO SUS \u0938\u0947 \u091c\u093e\u0902\u091a\u093e \xb7 nosus.foo","\u092e\u093e\u091d\u094d\u092f\u093e \u092b\u094b\u0928\u0935\u0930 NO SUS \u0928\u0947 \u0924\u092a\u093e\u0938\u0932\u0902 \xb7 nosus.foo")
B.bxV=new A.ec("Got a message that feels off? Nox reads it.","\u0915\u094b\u0908 \u092e\u0948\u0938\u0947\u091c \u0905\u091c\u0940\u092c \u0932\u0917\u093e? Nox \u092a\u0922\u093c\u0915\u0930 \u092c\u0924\u093e\u090f\u0917\u093e\u0964","\u090f\u0916\u093e\u0926\u093e \u092e\u0947\u0938\u0947\u091c \u0935\u093f\u091a\u093f\u0924\u094d\u0930 \u0935\u093e\u091f\u0932\u093e? Nox \u0935\u093e\u091a\u0942\u0928 \u0938\u093e\u0902\u0917\u0947\u0932.")
B.bxW=new A.ec("Call 1930 now and tell your bank. Reporting in the first hours gives the bank the best chance to hold the money.","\u0905\u092d\u0940 1930 \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092c\u0948\u0902\u0915 \u0915\u094b \u092c\u0924\u093e\u090f\u0902\u0964 \u092a\u0939\u0932\u0947 \u0915\u0941\u091b \u0918\u0902\u091f\u094b\u0902 \u092e\u0947\u0902 \u0936\u093f\u0915\u093e\u092f\u0924 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092c\u0948\u0902\u0915 \u0915\u0947 \u092a\u093e\u0938 \u092a\u0948\u0938\u093e \u0930\u094b\u0915\u0928\u0947 \u0915\u093e \u0938\u092c\u0938\u0947 \u0905\u091a\u094d\u091b\u093e \u092e\u094c\u0915\u093e \u0939\u094b\u0924\u093e \u0939\u0948\u0964","\u0906\u0924\u094d\u0924\u093e\u091a 1930 \u0935\u0930 \u0915\u0949\u0932 \u0915\u0930\u093e \u0906\u0923\u093f \u092c\u0901\u0915\u0947\u0932\u093e \u0915\u0933\u0935\u093e. \u092a\u0939\u093f\u0932\u094d\u092f\u093e \u0915\u093e\u0939\u0940 \u0924\u093e\u0938\u093e\u0902\u0924 \u0924\u0915\u094d\u0930\u093e\u0930 \u0915\u0947\u0932\u094d\u092f\u093e\u0938 \u092c\u0901\u0915\u0947\u0932\u093e \u092a\u0948\u0938\u0947 \u0925\u093e\u0902\u092c\u0935\u0923\u094d\u092f\u093e\u091a\u0940 \u0938\u0930\u094d\u0935\u093e\u0924 \u091a\u093e\u0902\u0917\u0932\u0940 \u0938\u0902\u0927\u0940 \u092e\u093f\u0933\u0924\u0947.")
B.bxX=new A.ec("Before you do anything, ask the bank or company on their official number.","\u0915\u0941\u091b \u092d\u0940 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092c\u0948\u0902\u0915 \u092f\u093e \u0915\u0902\u092a\u0928\u0940 \u0915\u0947 \u0911\u092b\u093c\u093f\u0936\u093f\u092f\u0932 \u0928\u0902\u092c\u0930 \u092a\u0930 \u092a\u0942\u091b \u0932\u0947\u0902\u0964","\u0915\u093e\u0939\u0940\u0939\u0940 \u0915\u0930\u0923\u094d\u092f\u093e\u0906\u0927\u0940 \u092c\u0901\u0915\u0947\u0932\u093e \u0915\u093f\u0902\u0935\u093e \u0915\u0902\u092a\u0928\u0940\u0932\u093e \u0924\u094d\u092f\u093e\u0902\u091a\u094d\u092f\u093e \u0905\u0927\u093f\u0915\u0943\u0924 \u0928\u0902\u092c\u0930\u0935\u0930 \u0935\u093f\u091a\u093e\u0930\u093e.")
